BEGIN;
CREATE SEQUENCE task_fencing_token_seq AS bigint;
CREATE TABLE factory_controls (singleton boolean PRIMARY KEY DEFAULT true CHECK(singleton), emergency_stopped boolean NOT NULL DEFAULT false);
INSERT INTO factory_controls(singleton,emergency_stopped) VALUES(true,false);
CREATE TABLE factory_contracts (id uuid PRIMARY KEY, baseline_sha char(40) NOT NULL, status text NOT NULL CHECK(status IN ('draft','active','verifying','succeeded','failed','cancelled')), max_cost_usd_micros bigint NOT NULL CHECK(max_cost_usd_micros>=0), spent_usd_micros bigint NOT NULL DEFAULT 0 CHECK(spent_usd_micros>=0), publication_preparing boolean NOT NULL DEFAULT false, prepared_sha char(40), published_sha char(40));
CREATE TABLE milestones (id uuid PRIMARY KEY, contract_id uuid NOT NULL REFERENCES factory_contracts(id), ordinal integer NOT NULL CHECK(ordinal>0), status text NOT NULL CHECK(status IN ('pending','active','succeeded','failed','cancelled')), UNIQUE(contract_id,ordinal), UNIQUE(id,contract_id));
CREATE TABLE tasks (id uuid PRIMARY KEY, contract_id uuid NOT NULL REFERENCES factory_contracts(id), milestone_id uuid NOT NULL, idempotency_key text NOT NULL, state text NOT NULL CHECK(state IN ('draft','queued','leased','running','verifying','retry_wait','needs_approval','budget_blocked','succeeded','failed','cancelled')), max_cost_usd_micros bigint NOT NULL CHECK(max_cost_usd_micros>=0), spent_usd_micros bigint NOT NULL DEFAULT 0 CHECK(spent_usd_micros>=0), attempt_count integer NOT NULL DEFAULT 0 CHECK(attempt_count>=0), max_attempts integer NOT NULL CHECK(max_attempts>0), next_attempt_at timestamptz, FOREIGN KEY(milestone_id,contract_id) REFERENCES milestones(id,contract_id), UNIQUE(contract_id,idempotency_key));
CREATE TABLE task_leases (task_id uuid PRIMARY KEY REFERENCES tasks(id), worker_id text NOT NULL, fencing_token bigint NOT NULL DEFAULT nextval('task_fencing_token_seq') UNIQUE, heartbeat_at timestamptz NOT NULL, expires_at timestamptz NOT NULL CHECK(expires_at>heartbeat_at));
CREATE TABLE task_attempts (id uuid PRIMARY KEY, task_id uuid NOT NULL REFERENCES tasks(id), ordinal integer NOT NULL CHECK(ordinal>0), state text NOT NULL CHECK(state IN ('leased','running','verifying','retry_wait','succeeded','failed','cancelled')), failure_reason text CHECK(failure_reason IN ('rate_limit','timeout','invalid_output','verification','authentication','provider_outage','budget','policy','worker')), started_at timestamptz NOT NULL, finished_at timestamptz, UNIQUE(task_id,ordinal));
CREATE TABLE task_costs (cost_id text PRIMARY KEY, task_id uuid NOT NULL, attempt_ordinal integer NOT NULL CHECK(attempt_ordinal>0), amount_usd_micros bigint NOT NULL CHECK(amount_usd_micros>=0), occurred_at timestamptz NOT NULL, FOREIGN KEY(task_id,attempt_ordinal) REFERENCES task_attempts(task_id,ordinal));
CREATE TRIGGER task_costs_immutable BEFORE UPDATE OR DELETE ON task_costs FOR EACH ROW EXECUTE FUNCTION reject_immutable_mutation();
CREATE TRIGGER task_costs_no_truncate BEFORE TRUNCATE ON task_costs FOR EACH STATEMENT EXECUTE FUNCTION reject_immutable_mutation();
CREATE TABLE gate_evidence (gate_id text NOT NULL, contract_id uuid NOT NULL REFERENCES factory_contracts(id), evidence_id uuid NOT NULL, passed boolean NOT NULL, PRIMARY KEY(gate_id,contract_id,evidence_id));
COMMIT;
